//! 🧪️ Neutral backing witnesses exercise refused, borrowed and final mask releases.
use super::*;
use semio_framework_value::{retirement::controlled::ControlledRetirement,retained_clone::{RetainedCloneStep,RetainedCloneGrant}};
pub(crate) fn observed<T>(step:impl FnOnce()->T)->(T,(usize,usize)){let(output,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(step);assert!(!heap.overflowed,"physical test allocator observation overflow");(output,(heap.requested_bytes,heap.released_bytes))}
#[path="../../../🌱️value/♻️retirement/📦️owner/🧪️work/effect.rs"]
pub(crate) mod effect;
/// 🪢️ One retirement turn inside one actual original effect with the heap scope around the owner action only.
pub(crate) fn turned(grant:RetainedCloneGrant,run:impl FnOnce(&mut semio_framework_value::RetainedAllocationEffect<'_>)->semio_framework_value::RetainedWorkPoll<RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>)->(RetainedCloneStep,(usize,usize)){let(poll,physical)=effect::with_effect(grant,1<<20,&mut None,|effect|observed(||run(effect)));(effect::settled(poll).result.unwrap(),physical)}
/// 🪢️ Like `turned` but a refused turn answers `None`, so a drain can try the next quoting body.
fn try_turned(grant:RetainedCloneGrant,run:impl FnOnce(&mut semio_framework_value::RetainedAllocationEffect<'_>)->semio_framework_value::RetainedWorkPoll<RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>)->Option<(RetainedCloneStep,(usize,usize))>{let(poll,physical)=effect::with_effect(grant,1<<20,&mut None,|effect|observed(||run(effect)));effect::settled(poll).result.ok().map(|step|(step,physical))}
pub(crate) fn drain<T:RetireOwned>(value:T)->(usize,usize){drain_owner(ControlledRetirement::new(value).unwrap_or_else(|(error,_)|panic!("unsupported test owner: {error}")))}
/// 🪢️ Drives an already retained owner to its terminal state over quoted one-item turns.
pub(crate) fn drain_owner<T:RetireOwned>(mut owner:ControlledRetirement<T>)->(usize,usize){
 let mut allocated=0;let mut released=0;
 for _ in 0..2_000_000 {if owner.terminal_is_empty(){break;}
  let bodies=[owner.next_copy_byte_demand().unwrap(),1<<16,owner.next_demand(1<<30).map_or(1<<16,|demand|demand.copy_bytes)];let mut progressed=false;
  for body in bodies{
   let Ok(demand)=owner.next_demand(body)else{continue};if demand.copy_bytes>body{continue}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};
   if let Some((zero,physical))=try_turned(RetainedCloneGrant{maximum_items:0,..grant},|effect|owner.step(grant.maximum_copy_bytes,effect)){assert_eq!(physical,(0,0));assert!(matches!(zero,RetainedCloneStep::Progress(p)if p==Default::default()));}
   let Some((step,physical))=try_turned(grant,|effect|owner.step(grant.maximum_copy_bytes,effect))else{continue};let (RetainedCloneStep::Progress(receipt)|RetainedCloneStep::Complete(receipt))=step;if receipt==Default::default()&&!owner.terminal_is_empty(){continue}
   assert!(receipt.fits(grant));assert!(physical.0<=grant.maximum_capacity_bytes,"physical allocation {} exceeds capacity {}",physical.0,grant.maximum_capacity_bytes);assert!(physical.1<=grant.maximum_release_bytes,"physical release {} exceeds funded release {}",physical.1,grant.maximum_release_bytes);assert_eq!(physical.0,receipt.retained_capacity_bytes);assert_eq!(physical.1,receipt.released_bytes);allocated+=physical.0;released+=physical.1;progressed=true;break;
  }
  assert!(progressed,"no quoting body funds the next close step");
 }
 assert!(owner.terminal_is_empty());let (_,physical)=observed(||drop(owner));assert_eq!(physical,(0,0));(allocated,released)
}
#[path="../../../◻️2d/🛤️path/🎟️work/🧪️tests/🦀️.rs"] pub(crate) mod test_wallet;
pub(crate) use test_wallet::Wallet;
pub(crate) fn physical_wallet()->Wallet{let value:serde_json::Value=serde_json::from_str(crate::text("🖊️coverage/🎟️work/🧫️fixtures/🔣️.json")).unwrap();let stock=&value["stock"];let n=|key|stock[key].as_u64().unwrap()as usize;Wallet::from_grant(RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copy"),maximum_capacity_bytes:n("capacity"),maximum_release_bytes:n("release"),maximum_depth:n("depth")},value["maximumTurns"].as_u64().unwrap()as usize)}
pub(crate) fn funded_turn<R>(wallet:&mut Wallet,items:usize,run:impl FnOnce(&mut semio_framework_value::work::RetainedWorkLedger,&mut Option<usize>)->R)->R{wallet.turn_observed(items,|work|{let(result,(allocated,released))=observed(||run(work,&mut None));(result,test_wallet::HeapObservation{requested_bytes:allocated,released_bytes:released,overflowed:false})})}
/// 🪢️ One funded turn of a 2d job inside one actual original effect.
pub(crate) fn funded_effect_turn<R>(wallet:&mut Wallet,items:usize,run:impl FnOnce(&mut semio_framework_value::work::RetainedWorkLedger,&mut semio_framework_value::RetainedAllocationEffect<'_>)->R)->R{wallet.turn_effect(items,run)}
pub(crate) fn funded_close_owned<T:RetireOwned>(value:T,wallet:&mut Wallet)->(usize,usize){let(mut owner,heap)=observed(||ControlledRetirement::retain(value));assert_eq!(heap,(0,0));let mut total=(0,0);for _ in 0..2_000_000{if owner.terminal_is_empty(){break}let body=wallet.remaining().maximum_copy_bytes;let d=owner.next_demand(body).unwrap();let step=wallet.close_turn_observed(d,|effect|{let(result,(allocated,released))=observed(||owner.step(body,effect));total.0+=allocated;total.1+=released;(result,test_wallet::HeapObservation{requested_bytes:allocated,released_bytes:released,overflowed:false})}).unwrap();assert_ne!(step.progress(),Default::default());}assert!(owner.terminal_is_empty());let((),heap)=observed(||drop(owner));assert_eq!(heap,(0,0));total}
#[test]
fn retained_physical_raster_children_obey_allocator_grants(){
 use crate::{coverage::{CoverageInput,CoverageJob,CoverageRule},affine_sampling::{AffineImageInput,AffineImageJob,AffineSampling},compositing::{CompositeJob,CompositeLayer,CompositeContent,CompositeBlend}};
 let fixture:serde_json::Value=serde_json::from_str(crate::text("♻️retirement/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for stop in fixture["interruptions"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){
  let mut wallet=physical_wallet();let mut coverage=CoverageJob::new(CoverageInput{width:8,height:8,transform:[1.,0.,0.,1.,0.,0.],rule:CoverageRule::NonZero,contours:vec![vec![[0.,0.],[8.,0.],[8.,8.],[0.,8.]]]});if stop>0{funded_turn(&mut wallet,stop,|work,alloc|coverage.advance(stop,work,alloc)).unwrap();}coverage.cancel();let retired=coverage.into_retirement().0;let(a,r)=funded_close_owned(retired,&mut wallet);assert!(r>a);
  let source=Arc::new(RasterImage{width:2,height:2,pixels:vec![255;16]});let mut wallet=physical_wallet();let mut sample=AffineImageJob::new(AffineImageInput{source:source.clone(),width:8,height:8,origin:[0.,0.],transform:[4.,0.,0.,4.,0.,0.],sampling:AffineSampling::Area});if stop>0{funded_turn(&mut wallet,stop,|work,alloc|sample.advance(stop,work,alloc)).unwrap();}sample.cancel();let(a,r)=funded_close_owned(sample.into_retirement(),&mut wallet);if stop==0{assert_eq!(r,a);}else{assert!(r>=a);}assert_eq!(source.pixels,vec![255;16]);assert_eq!(Arc::strong_count(&source),1);
  let mut wallet=physical_wallet();let mut compositor=CompositeJob::new_owned(8,8,[0.,0.],vec![("image".into(),RasterLease(source.clone()))],vec![CompositeLayer{opacity:1.,blend:CompositeBlend::Normal,visible:true,transform:[4.,0.,0.,4.,0.,0.],mask:None,content:CompositeContent::Pixels("image".into())}]);if stop>0{funded_turn(&mut wallet,stop,|work,alloc|compositor.advance(stop,work,alloc)).unwrap();}compositor.cancel();let(a,r)=funded_close_owned(compositor.into_retirement(),&mut wallet);assert!(r>a);assert_eq!(Arc::strong_count(&source),1);
 }
}
#[test]
fn retained_physical_geometry_children_obey_allocator_grants(){
 use semio_framework_2d::{PathSegment,flatten::{PathFlattenInput,PathFlattenJob},stroke::{StrokeOutlineInput,StrokeOutlineJob,StrokeContour,StrokeGeometryStyle,StrokeGeometryCap,StrokeGeometryJoin}};
 let fixture:serde_json::Value=serde_json::from_str(crate::text("♻️retirement/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for stop in fixture["interruptions"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){
  let mut wallet=physical_wallet();let mut flatten=PathFlattenJob::new(PathFlattenInput{segments:vec![PathSegment::Move{to:[0.,0.]},PathSegment::Cubic{ctrl1:[0.,8.],ctrl2:[8.,8.],to:[8.,0.]},PathSegment::Close],transform:[1.,0.,0.,1.,0.,0.],tolerance:0.1});if stop>0{let mut reached=false;for _ in 0..2_000_000{let p=funded_effect_turn(&mut wallet,1,|work,alloc|flatten.advance(1,work,alloc)).unwrap();if p.work>=stop as u64||p.done{reached=true;break;}}assert!(reached);}flatten.cancel();let((retired,output),heap)=observed(||flatten.into_retirement());assert_eq!(heap,(0,0));assert!(output.is_none());let(a,r)=funded_close_owned(retired,&mut wallet);assert!(r>a);
  let mut wallet=physical_wallet();let mut stroke=StrokeOutlineJob::new(StrokeOutlineInput{contours:vec![StrokeContour{points:vec![[0.,0.],[8.,0.],[8.,8.]],closed:false}],transform:[1.,0.,0.,1.,0.,0.],tolerance:0.1,style:StrokeGeometryStyle{width:2.,cap:StrokeGeometryCap::Round,join:StrokeGeometryJoin::Round,miter_limit:4.,dash:vec![1.,1.],dash_offset:0.}});if stop>0{let mut reached=false;for _ in 0..2_000_000{let p=funded_effect_turn(&mut wallet,1,|work,alloc|stroke.advance(1,work,alloc)).unwrap();if p.work>=stop as u64||p.done{reached=true;break;}}assert!(reached);}stroke.cancel();let((retired,output),heap)=observed(||stroke.into_retirement());assert_eq!(heap,(0,0));assert!(output.is_none());let(a,r)=funded_close_owned(retired,&mut wallet);assert!(r>a);
 }
}
#[test]
fn retained_physical_numeric_scratch_matches_reference_and_allocator(){
 use semio_framework_value::numeric_scratch::NumericIndex;use std::collections::BTreeMap;
 let fixture:serde_json::Value=serde_json::from_str(crate::text("../🌱️value/🗂️ordered/🔢️numeric/🧮️scratch/🧪️tests/📜️fixtures/🔣️.json")).unwrap();let mut index=NumericIndex::<i64,i64>::new();let mut oracle=BTreeMap::new();let mut output=Vec::new();
 for row in fixture["operations"].as_array().unwrap(){let key=row["key"].as_i64().unwrap_or(0);let result=match row["kind"].as_str().unwrap(){"set"=>{let value=row["value"].as_i64().unwrap();let actual=index.insert(key,value);assert_eq!(actual,oracle.insert(key,value));serde_json::json!(actual)},"remove"=>{let actual=index.remove(&key);assert_eq!(actual,oracle.remove(&key));serde_json::json!(actual)},"get"=>{let actual=index.get(&key).copied();assert_eq!(actual,oracle.get(&key).copied());serde_json::json!(actual)},"first"=>{let actual=index.pop_first();assert_eq!(actual,oracle.pop_first());serde_json::json!(actual.map(|(key,value)|[key,value]))},"reset"=>{index.reset();oracle.clear();serde_json::Value::Null},_=>unreachable!()};assert_eq!(index.len(),oracle.len());output.push(result);}
 assert_eq!(serde_json::json!(output),fixture["expected"]);for key in 0..4096{index.insert(key,key);}let stored=index.stored_keys();index.reset();for key in (0..4096).rev(){index.insert(key,key);}assert_eq!(index.stored_keys(),stored);for key in 0..4096{assert_eq!(index.pop_first(),Some((key,key)));}assert!(index.is_empty());let(a,r)=drain(index);assert!(r>a);
}
#[test]
fn retained_physical_boolean_and_trace_children_obey_allocator_grants(){
 use semio_framework_2d::{PathSegment,booleans::{BooleanJob,BooleanInput,BooleanOperand,BooleanOperation,BooleanFillRule},trace::{BitmapTraceJob,BitmapTraceInput}};
 let boolean_rows:serde_json::Value=serde_json::from_str(crate::text("../◻️2d/🔀️booleans/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let trace_rows:serde_json::Value=serde_json::from_str(crate::text("../◻️2d/🔍️trace/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in boolean_rows.as_array().unwrap(){let input=&row["input"];let source=BooleanInput{operation:BooleanOperation::parse(input["operation"].as_str().unwrap()).unwrap(),operands:input["operands"].as_array().unwrap().iter().map(|operand|BooleanOperand{fill_rule:if operand["fillRule"]=="evenodd"{BooleanFillRule::Evenodd}else{BooleanFillRule::Nonzero},contours:operand["contours"].as_array().unwrap().iter().map(|ring|ring.as_array().unwrap().iter().map(|p|[p[0].as_f64().unwrap(),p[1].as_f64().unwrap()]).collect()).collect()}).collect(),epsilon:input["epsilon"].as_f64().unwrap(),max_edges:input["maxEdges"].as_u64().unwrap()as usize,max_parameters:input["maxParameters"].as_u64().unwrap()as usize,max_atomic_edges:input["maxAtomicEdges"].as_u64().unwrap()as usize,max_segments:input["maxSegments"].as_u64().unwrap()as usize,max_work:input["maxWork"].as_u64().unwrap()};
  for stop in [0,1,10,100,4096]{let mut wallet=physical_wallet();let mut job=BooleanJob::new(source.clone());if stop>0{funded_effect_turn(&mut wallet,stop,|work,alloc|job.advance(stop,work,alloc)).unwrap();}job.cancel();let(retired,operands,output)=job.into_retirement();assert!(output.is_none());drain(retired);drain(operands);}
  let mut wallet=physical_wallet();let mut job=BooleanJob::new(source);while !funded_effect_turn(&mut wallet,4096,|work,alloc|job.advance(4096,work,alloc)).unwrap().done{}let(retired,operands,output)=job.into_retirement();let output=output.unwrap();let mut first=[0.;2];let mut previous=[0.;2];let mut area=0.;let mut contours=0;for segment in &output{match segment{PathSegment::Move{to}=>{first=*to;previous=*to;contours+=1;},PathSegment::Line{to}=>{area+=previous[0]*to[1]-to[0]*previous[1];previous=*to;},PathSegment::Close=>area+=previous[0]*first[1]-first[0]*previous[1],_=>unreachable!()}}assert_eq!(contours,row["expected"]["contours"].as_u64().unwrap());assert!((area/2.-row["expected"]["area"].as_f64().unwrap()).abs()<1e-5);drain(retired);drain(operands);drain(output);
 }
 for row in trace_rows.as_array().unwrap(){let input=&row["input"];let source=BitmapTraceInput{width:input["width"].as_u64().unwrap()as u32,height:input["height"].as_u64().unwrap()as u32,mask:input["mask"].as_array().unwrap().iter().map(|p|p.as_u64().unwrap()as u8).collect::<Vec<_>>(),threshold:input["threshold"].as_f64().unwrap(),simplify_epsilon:input["simplifyEpsilon"].as_f64().unwrap(),max_pixels:input["maxPixels"].as_u64().unwrap()as usize,max_edges:input["maxEdges"].as_u64().unwrap()as usize,max_segments:input["maxSegments"].as_u64().unwrap()as usize,max_work:input["maxWork"].as_u64().unwrap()};for stop in [0,1,10,100,4096]{let mut wallet=physical_wallet();let mut job=BitmapTraceJob::new(source.clone());if stop>0{funded_effect_turn(&mut wallet,stop,|work,alloc|job.advance(stop,work,alloc)).unwrap();}job.cancel();let(retired,mask)=job.into_retirement();assert_eq!(mask.as_ref(),Some(&source.mask));drain(retired);drain(mask);}let mut wallet=physical_wallet();let mut job=BitmapTraceJob::new(source);while !funded_effect_turn(&mut wallet,4096,|work,alloc|job.advance(4096,work,alloc)).unwrap().done{}assert_eq!(job.result().unwrap().iter().filter(|s|matches!(s,PathSegment::Move{..})).count(),row["expected"]["contours"].as_u64().unwrap()as usize);let(retired,mask)=job.into_retirement();drain(retired);drain(mask);}
}
#[test]
fn retained_physical_png_encoder_obeys_allocator_grants(){
 use crate::png_encoding::PngEncodeJob;
 for stop in [0,1,2]{let mut job=PngEncodeJob::new(RasterImage{width:8,height:8,pixels:vec![127;256]}).unwrap();for _ in 0..stop{job.advance().unwrap();}job.cancel();assert!(job.result().is_err());let(a,r)=drain(job);assert!(r>a);}
 let expected=vec![127;256];let mut job=PngEncodeJob::new(RasterImage{width:8,height:8,pixels:expected.clone()}).unwrap();while !job.advance().unwrap().done{}let output=job.take_result().unwrap();let(a,r)=drain(job);assert!(r>a);
 let mut decoder=png::Decoder::new(std::io::Cursor::new(&output.data)).read_info().unwrap();let mut pixels=vec![0;decoder.output_buffer_size()];let info=decoder.next_frame(&mut pixels).unwrap();assert_eq!((info.width,info.height),(8,8));assert_eq!(pixels[..info.buffer_size()],expected);
 drain(output);
}
#[test]
fn retained_physical_mask_leases_require_actual_backing_grants(){
 let fixture:serde_json::Value=serde_json::from_str(crate::text("♻️retirement/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap().iter().filter(|row|row["input"]["kind"]=="mask"){
  let bytes:Vec<u8>=row["input"]["bytes"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect();let lease=MaskLease::from(bytes.clone());let source=lease.0;
  let alias=(row["input"]["aliases"].as_u64().unwrap()>0).then(||source.clone());let weak=(row["input"]["weakLeases"].as_u64().unwrap()>0).then(||Arc::downgrade(&source));
  let demand=semio_framework_value::retirement::arc_custody::shared_retirement_allocation_bytes::<MaskBytes>();let mut cursor=ControlledRetirement::new(semio_framework_value::retirement::arc_custody::ArcLease::new(source)).unwrap_or_else(|(error,_)|panic!("unsupported lease: {error}"));let quote=cursor.next_demand(0).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:quote.copy_bytes,maximum_release_bytes:demand,maximum_capacity_bytes:0,maximum_depth:1};
  let(zero,physical)=turned(RetainedCloneGrant{maximum_items:0,..grant},|effect|cursor.step(grant.maximum_copy_bytes,effect));assert!(matches!(zero,RetainedCloneStep::Progress(p)if p==Default::default()));assert_eq!(physical,(0,0));
  if let Some(weak)=weak{let(step,physical)=turned(grant,|effect|cursor.step(grant.maximum_copy_bytes,effect));let RetainedCloneStep::Progress(receipt)=step else{panic!("funded weak lease did not close")};assert_eq!(receipt.released_bytes,0);assert_eq!(physical,(0,0));assert!(weak.upgrade().is_none());let((),physical)=observed(||drop(weak));assert_eq!(physical,(0,demand));drain_owner(cursor);continue;}
  let(step,physical)=turned(RetainedCloneGrant{maximum_release_bytes:demand-1,..grant},|effect|cursor.step(grant.maximum_copy_bytes,effect));assert!(matches!(step,RetainedCloneStep::Progress(p)if p==Default::default()));assert_eq!(physical,(0,0));
  let mut released=0;for _ in 0..64{if cursor.terminal_is_empty(){break}let d=cursor.next_demand(0).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,physical)=turned(g,|effect|cursor.step(0,effect));let RetainedCloneStep::Progress(receipt)=step else{panic!("funded lease did not close")};assert_eq!(physical,(receipt.retained_capacity_bytes,receipt.released_bytes));released+=u64::from(receipt.released_bytes==demand)as usize;}assert_eq!(released,if alias.is_some(){0}else{1},"the Arc backing is released exactly once and only without aliases");drain_owner(cursor);if let Some(alias)=alias{assert_eq!(alias.0,bytes);}
 }
}
#[test]
fn retained_physical_curved_boolean_children_obey_allocator_grants(){
 use semio_framework_2d::{PathSegment,booleans::{BooleanOperation,BooleanFillRule,paths::{PathBooleanJob,PathBooleanInput,PathBooleanOperand}}};
 fn point(value:&serde_json::Value)->[f64;2]{[value[0].as_f64().unwrap(),value[1].as_f64().unwrap()]}
 fn segment(value:&serde_json::Value)->PathSegment{match value["kind"].as_str().unwrap(){"move"=>PathSegment::Move{to:point(&value["to"])},"line"=>PathSegment::Line{to:point(&value["to"])},"quad"=>PathSegment::Quad{ctrl:point(&value["ctrl"]),to:point(&value["to"])},"cubic"=>PathSegment::Cubic{ctrl1:point(&value["ctrl1"]),ctrl2:point(&value["ctrl2"]),to:point(&value["to"])},"arc"=>PathSegment::Arc{rx:value["rx"].as_f64().unwrap(),ry:value["ry"].as_f64().unwrap(),rotation:value["rotation"].as_f64().unwrap(),large_arc:value["largeArc"].as_bool().unwrap(),sweep:value["sweep"].as_bool().unwrap(),to:point(&value["to"])},"close"=>PathSegment::Close,_=>unreachable!()}}
 let fixture:serde_json::Value=serde_json::from_str(crate::text("../◻️2d/🔀️booleans/🛤️paths/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let source=PathBooleanInput{operation:BooleanOperation::parse(row["operation"].as_str().unwrap()).unwrap(),operands:row["operands"].as_array().unwrap().iter().map(|v|PathBooleanOperand{segments:v["segments"].as_array().unwrap().iter().map(segment).collect(),transform:std::array::from_fn(|i|v["transform"][i].as_f64().unwrap()),tolerance:v["tolerance"].as_f64().unwrap(),fill_rule:if v["fillRule"]=="evenodd"{BooleanFillRule::Evenodd}else{BooleanFillRule::Nonzero}}).collect(),epsilon:1e-8,max_edges:65536,max_parameters:262144,max_atomic_edges:65536,max_segments:65536,max_work:10000000};
  for stop in [0,1,10,100,4096]{let mut wallet=physical_wallet();let mut job=PathBooleanJob::new(source.clone());if stop>0{funded_effect_turn(&mut wallet,stop,|work,alloc|job.advance(stop,work,alloc)).unwrap();}job.cancel();let(retired,output)=job.into_retirement();assert!(output.is_none());drain(retired);}
  let mut wallet=physical_wallet();let mut job=PathBooleanJob::new(source);while !funded_effect_turn(&mut wallet,4096,|work,alloc|job.advance(4096,work,alloc)).unwrap().done{}let(retired,output)=job.into_retirement();let output=output.unwrap();assert_eq!(output.iter().filter(|s|matches!(s,PathSegment::Move{..})).count(),row["contours"].as_u64().unwrap()as usize);drain(retired);drain(output);
 }
}
